int f(vector<int> const& a, int l) {
	int res = 0;
	int p = 1;
	for (int i = 0; i < max(szof(a), l); ++i) {
		if (i < l) {
			p = mult(p, 10);
		}
		if (i < szof(a)) {
			add(res, mult(a[i], p));
			p = mult(p, 10);
		}
	}
	return res;
}

int f(int l, vector<int> const& b) {
	int res = 0;
	int p = 1;
	for (int i = 0; i < max(l, szof(b)); ++i) {
		if (i < szof(b)) {
			add(res, mult(b[i], p));
			p = mult(p, 10);
		}
		if (i < l) {
			p = mult(p, 10);
		}
	}
	return res;
